values ('53c43106-46e6-4cb6-ae76-6a59601dd3b4', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "6753d4d2-6086-4292-afa8-9a3c0761afaf", "heading": "Dates & Rates", "manual_dates_text": "Nov 28 - Dec 5, 2026", "manual_tiers": [{"name": "Dorm", "price": "$1095"}, {"name": "Triple", "price": "$1,295"}, {"name": "Double", "price": "$1,595"}, {"name": "Single", "price": "$2,195"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.secure.retreat.guru/program/becoming-yoga-retreat-colynn-cespedes/?form=1&lang=en"}'::jsonb)
