insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('53c43106-46e6-4cb6-ae76-6a59601dd3b4', 'c229572b-1c0d-446e-8c7c-f05b2852bb92', '{"html": "<p><strong>Something in you is shifting. This retreat gives it room to move.</strong></p><p>Becoming is a week-long, body-centered retreat at Anamaya in Costa Rica, built around one guiding question: who are you becoming?</p><p>Through optional somatic yoga, nervous system practices, guided reflection, and ceremony, this retreat moves intentionally through three phases \u2013 your past, your present, and your future.</p><p>Each day unfolds gently, giving your body and mind space to process, release, and clarify. Set within lush jungle and ocean air, this is not a passive reset. It is a structured, compassionate journey back to yourself.</p><p><strong>Come curious. Leave changed.</strong></p>", "padding_y_px": 48}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('53c43106-46e6-4cb6-ae76-6a59601dd3b4', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "Becoming Aware: Past", "price": "$40", "note": "90-minute workshop"}, {"name": "Becoming Present: Present", "price": "$40", "note": "90-minute workshop"}, {"name": "Becoming Clear: Future", "price": "$40", "note": "90-minute workshop"}, {"name": "Becoming Whole: Celebration", "price": "$50", "note": "120-minute workshop"}, {"name": "PACKAGE PRICE for all 4 workshops", "price": "$150"}], "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('53c43106-46e6-4cb6-ae76-6a59601dd3b4', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>Becoming Aware: Past</h3><p><em>90-minute workshop &mdash; $40</em></p><p>We begin here. This grounding session explores how past experiences, stress, and relationships continue to shape how we move through the world today, not just in the mind, but in the body. Through somatic practice and gentle reflection, you\u2019ll start noticing patterns with curiosity rather than judgment. This Workshop is 90 minutes. Price is $40.</p><h3>Becoming Present: Present</h3><p><em>90-minute workshop &mdash; $40</em></p><p>An experiential workshop that brings you fully into now. Through guided movement, breath, and embodied awareness, this session supports emotional expression, releases stored tension, and invites your nervous system into regulation. It closes with stillness and time to integrate what has shifted. This Workshop is 90 minutes. Price is $40.</p><h3>Becoming Clear: Future</h3><p><em>90-minute workshop &mdash; $40</em></p><p>From a place of grounded presence, we turn toward what\u2019s next. This session explores how clarity and healthy boundaries arise from listening to the body, not forcing it. You\u2019ll learn to recognize your own inner signals and move forward with confidence and alignment. This Workshop is 90 minutes. Price is $40.</p><h3>Becoming Whole: Celebration</h3><p><em>120-minute workshop &mdash; $50</em></p><p>We close the week with a heart-opening cacao ceremony. Through ritual, music, movement, and shared presence, we honor what has shifted, what has been released, and what is beginning. A beautiful, joyful celebration of your becoming. This Workshop is 2 hours. Price is $50.</p><h3>PACKAGE PRICE for all 4 workshops</h3><p><em>$150</em></p><h4>PACKAGE PRICE: For all 4 workshops is $150.</h4>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('53c43106-46e6-4cb6-ae76-6a59601dd3b4', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/ee6afaac-3f31-42b9-a5d4-feea52aa96e4/gallery/hero-image-82-5d39039d.png", "alt": "Becoming Retreat \u2013 Colynn Cespedes"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/ee6afaac-3f31-42b9-a5d4-feea52aa96e4/gallery/lower-deck-yoga-class-cropped-300x300-51700eee.png", "alt": "Becoming Retreat \u2013 Colynn Cespedes"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/relax-on-the-pool-deck-at-anamaya-resort-300x300-87bae3ad.jpg", "alt": "Becoming Retreat \u2013 Colynn Cespedes"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/spa-1-300x300-c701562a.jpg", "alt": "Becoming Retreat \u2013 Colynn Cespedes"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/cristiane-link-300x300-c44147a2.jpg", "alt": "Becoming Retreat \u2013 Colynn Cespedes"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/food-5-300x300-342b7e50.jpg", "alt": "Becoming Retreat \u2013 Colynn Cespedes"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/53c43106-46e6-4cb6-ae76-6a59601dd3b4/gallery/colynn-vosburgh-781x800-0dbf91b8.jpg", "alt": "Becoming Retreat \u2013 Colynn Cespedes"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('53c43106-46e6-4cb6-ae76-6a59601dd3b4', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Colynn Cespedes", "bio_html": "<p>Colynn Cespedes spent the first chapter of her career in healthcare. Starting as a Home Support Worker in 2000, she trained and worked her way through to Emergency Room Nursing before pursuing medical school. It was, by every measure, the path she had planned.</p><p>But yoga kept calling.</p><p>The two worlds couldn\u2019t have felt more different, and eventually, the contrast became impossible to ignore. Colynn made the decision to step away from medicine and move fully into yoga, coaching, and energy work. It was a leap that would define everything that followed.</p><p>Today, Colynn brings hundreds of Yoga Teacher Trainings and thousands of training hours into every room she teaches. Her classes draw from anatomy, energy work, humor, and hard-won life experience, weaving in past life regressions and spiritual depth alongside the practical and the real. For Colynn, the postures are an entry point: a way back into the body, a bridge between mind and soul, and an invitation to stop rushing and actually arrive.</p><p>At Anamaya, her mornings are dynamic and awakening, her evenings candlelit and slow. Between the two, students are guided not just to move, but to see things differently, loosen their grip on life\u2019s noise, and settle into true presence.</p><p>Colynn now lives nomadically, rooted most often in Costa Rica, sustained by the ocean, the jungle, and the communities she builds wherever she goes. Her work, whether through yoga, coaching, or healing, keeps returning to the same intention: help people find their way back to themselves.</p>", "ao_person_id": "39009e28-a1d6-4d97-be52-2ab901d904a6"}'::jsonb)
on conflict do nothing;
