values ('c0d23964-58fd-4eb5-9442-c6811429c729', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "638f9906-2c69-4881-8084-06fceb551f45", "heading": "Dates & Rates", "manual_dates_text": "Feb 6 - 13, 2027", "manual_tiers": [{"name": "Dorm", "price": "$1,095"}, {"name": "Triple", "price": "$1,295"}, {"name": "Double", "price": "$1,595"}, {"name": "Single", "price": "$2,195"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.secure.retreat.guru/program/freedom-embodied-retreat-pamela-fitzgerald-copy/?form=1&lang=en"}'::jsonb)
