values ('c0d23964-58fd-4eb5-9442-c6811429c729', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/c0d23964-58fd-4eb5-9442-c6811429c729/gallery/hero-image-40-da915857.png", "alt": "Freedom Embodied \u2013 Pamela Fitzgerald"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/relax-on-the-pool-deck-at-anamaya-resort-300x300-87bae3ad.jpg", "alt": "Freedom Embodied \u2013 Pamela Fitzgerald"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/c0d23964-58fd-4eb5-9442-c6811429c729/gallery/yoga_duarte39-300x300-6a28c9a7.jpg", "alt": "Freedom Embodied \u2013 Pamela Fitzgerald"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/spa-1-300x300-c701562a.jpg", "alt": "Freedom Embodied \u2013 Pamela Fitzgerald"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/c0d23964-58fd-4eb5-9442-c6811429c729/gallery/pamela-and-horse-3a6ca55a.png", "alt": "Freedom Embodied \u2013 Pamela Fitzgerald"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/c0d23964-58fd-4eb5-9442-c6811429c729/gallery/food_0013_layer-6-300x300-5fc353e5.jpg", "alt": "Freedom Embodied \u2013 Pamela Fitzgerald"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/c0d23964-58fd-4eb5-9442-c6811429c729/gallery/pamela-fitzgerald-photo-6f2606c9.png", "alt": "Freedom Embodied \u2013 Pamela Fitzgerald"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('c0d23964-58fd-4eb5-9442-c6811429c729', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Pamela Fitzgerald", "bio_html": "<p>Pamela is a 500-hour certified yoga teacher who found her way to yoga after a diverse and dynamic journey through the wellness world. With a background in gymnastics, dance, and horseback riding, her lifelong passion for movement and the outdoors led her into a career in wellness. She studied anatomy extensively across the U.S. and Canada, even teaching cadaver anatomy to fitness professionals, and was a strength trainer to pro athletes and post-operative patients. Pamela also became a published fitness model and bodybuilding competitor, achieving many accolades until she recognized the toll that stress, image struggles, and a disconnection from self were taking on her life.</p><p>Yoga found Pamela at this turning point, offering her a path to reconnect body, mind, and soul. Initially reluctant, she soon immersed herself in its philosophy, finding peace and renewal in practices that deepened her understanding of the body\u2019s stress responses. Today, she brings this profound journey to her students, guiding them toward self-love, self-discovery, and a mindful way of being.</p><p>Pamela now teaches yoga full-time, leading retreats across Canada, Costa Rica, and the U.S., often incorporating her beloved horse, Honeycomb, to create heart-centered experiences in nature. Her mission is to help students feel \u201cat home\u201d in their bodies, encouraging free expression, groundedness, and a deep connection to the present. <strong>Pamela\u2019s teachings focus on bringing yoga\u2019s beauty and wisdom into daily life, supporting a balanced, joyful approach to living fully and authentically.</strong></p>", "ao_person_id": "dad72794-80f5-4a7d-9595-e320a34dff7d"}'::jsonb)
on conflict do nothing;
