values ('97289f62-a766-47fb-8fdb-cfce88181c7c', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "Somatic Practice for Soul Expression", "price": "$45\u2013$110", "note": "90-minute workshop"}, {"name": "Wild Heart Ceremony: A Sacred Journey with Costa Rican Cacao", "price": "$45\u2013$110", "note": "90-minute workshop"}, {"name": "Creating with Intention: Crystal Totem Jewelry", "price": "$50\u2013$110", "note": "90-minute workshop"}], "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('97289f62-a766-47fb-8fdb-cfce88181c7c', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>Somatic Practice for Soul Expression</h3><p><em>90-minute workshop &mdash; $45\u2013$110</em></p><p><em>Learn the language of your body \u2014 and let your soul move you.</em></p><p>Your body holds stories, wisdom, and wild creative power. In this immersive somatic journey, you\u2019ll deepen your connection to your physical and energetic bodies through breath, sensation, and intuitive movement.</p><p>Discover how your body speaks to you, responds to emotion, and can be a powerful ally in both challenge and celebration. We\u2019ll weave in ecstatic dance, sound, and embodied release to free you from old patterns, awaken bold self-expression, and reignite your creative fire.</p><p>Come as you are. Move how you feel. Leave with a body that feels like home.</p><h3>Wild Heart Ceremony: A Sacred Journey with Costa Rican Cacao</h3><p><em>90-minute workshop &mdash; $45\u2013$110</em></p><p><em>Open your heart, awaken your senses, and remember your wild truth.</em></p><p>This heart-centered ritual blends the sacred wisdom of locally grown, ceremonial-grade cacao with breathwork, visualization, and soulful movement. Cacao is more than a drink &#8211; it\u2019s a gentle teacher that opens the emotional body, deepens authentic connection, and helps you listen inward.</p><p>You\u2019ll be guided through a sacred opening and offered space for movement, journaling, or stillness. We\u2019ll close with integration practices so this connection lives on long after the ceremony.</p><p>This is not just a ceremony&#8230; it\u2019s a homecoming to yourself.</p><h3>Creating with Intention: Crystal Totem Jewelry</h3><p><em>90-minute workshop &mdash; $50\u2013$110</em></p><p><em>A creative ritual to carry your transformation forward.</em></p><p>Choose stones and crystals that speak to your journey, then create a unique piece of jewelry infused with your intentions. As you design, you\u2019ll weave your growth, insights, and wisdom into every bead and thread.</p><p>More than a keepsake, this talisman will serve as a daily reminder of your embodied freedom and creativity. Includes reflection time and integration tools to help you bring your retreat experiences into your life at home.</p><p><strong>All materials provided.</strong></p><h3>Horse Spirit Meditation: Remembering the Wild Within</h3><p><em>90-minute workshop</em></p><p><em>A rare and sacred encounter with a free-living herd of healing horses.</em></p><p>In the stillness of the jungle, you\u2019ll meet a herd of sentient, sovereign beings who live in complete presence. Through meditation, somatic awareness, and intuitive movement, connect heart-to-heart with these ancient teachers.</p><p>Every session is unique &#8211; sometimes still and reverent, sometimes playful and emotionally charged. Always an invitation to remember the part of you that is wild, wise, and free.</p><h3>Private Yoga & Embodiment Sessions</h3><p><em>Personalized attention to deepen your practice and nurture your body.</em></p><p>One-on-one sessions are tailored to your goals &#8211; whether deepening your yoga practice, building a strong foundation, or exploring somatic healing. Each session blends mindful movement, breath, and embodiment practices to release tension, build strength, and cultivate presence.</p><p><span>Experience the freedom of a practice designed just for you. </span></p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
