values ('f13a95ab-df1c-4198-9318-587528baa434', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "9bc9e359-c30e-417e-a57f-91c39f6495ff", "heading": "Dates & Rates", "manual_dates_text": "Jan 2 - 9, 2027", "manual_tiers": [{"name": "Dorm", "price": "$1,095"}, {"name": "Triple", "price": "$1,295"}, {"name": "Double", "price": "$1,595"}, {"name": "Single", "price": "$2,195"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.secure.retreat.guru/program/new-year-retreat-costa-rica-gabriana-desousa/?form=1&lang=en"}'::jsonb)
