insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('f13a95ab-df1c-4198-9318-587528baa434', 'c229572b-1c0d-446e-8c7c-f05b2852bb92', '{"html": "<p><strong>Welcome to the New Year Kick-Off Retreat! A retreat designed to help you step into the new year with clarity, intention, and renewed energy.</strong></p><p>Through a blend of practical strategy and soulful exploration, you\u2019ll build a personalized wellness routine that weaves together movement, nourishment, and intentional recovery. Together, we\u2019ll integrate modern science with ancient wisdom to help you reconnect with your intuition and step into the strongest, calmest version of you.</p><p>This retreat is designed for anyone ready to reset and realign as they move into the new year, alongside those seeking sustainable habits that support both performance and well-being.</p><p>It\u2019s also a beautiful fit for those craving space to quiet the noise of daily life and reconnect with their inner wisdom through guided meditation, reflection, and intuitive practices.</p>", "padding_y_px": 48}'::jsonb)
