insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('f13a95ab-df1c-4198-9318-587528baa434', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Gabriana DeSousa", "bio_html": "<p>I am an Integrative Wellness Practitioner devoted to the art of restoring balance \u2013 in the body, the mind, the energy field, and the quiet spaces of the spirit. For over a decade, I\u2019ve walked the path of movement-based healing, weaving together custom therapeutic training, mindful movement, and Thai massage stretching to help the body remember its natural ease.</p><p>My journey has taken me around the world to study and train from master teachers, each shaping the way I hold space, guide breath, and invite stillness. Through yoga, meditation, and the ancient wisdom of Ayurveda, I help others reconnect with the rhythms that nourish and sustain them.</p><p>I also work with the unseen realms of energy \u2013 tuning into frequency and intuition \u2013 to gently unravel old patterns and awaken the deeper layers of healing that words alone cannot reach.</p><p>Whether you are seeking relief, renewal, or a return to yourself, this is a space where all parts of you are welcomed. <strong>Physical, mental, energetic, spiritual \u2013 your whole being is invited into the journey.</strong></p><p>Together, we\u2019ll follow the path toward clarity, wholeness, and a soul that feels at home in your body once again.</p>", "ao_person_id": "a25ece65-9698-484e-a14d-6f16cf57d796"}'::jsonb)
on conflict do nothing;
