values ('35420810-b051-4517-8442-44d2b3d44068', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/35420810-b051-4517-8442-44d2b3d44068/gallery/primal_return_who_its_for-a0cc3a05.png", "alt": "The Primal Return Retreat \u2013 Sierra Kliscz"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/35420810-b051-4517-8442-44d2b3d44068/gallery/property-pool-800x600-1-300x300-cc7e61f9.jpg", "alt": "The Primal Return Retreat \u2013 Sierra Kliscz"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/35420810-b051-4517-8442-44d2b3d44068/gallery/anamaya-retreat-community-300x300-09e6a8d8.png", "alt": "The Primal Return Retreat \u2013 Sierra Kliscz"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/spa-1-300x300-c701562a.jpg", "alt": "The Primal Return Retreat \u2013 Sierra Kliscz"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/35420810-b051-4517-8442-44d2b3d44068/gallery/330956845_487716986904044_3832568765049526636_n-300x300-d94e510b.jpg", "alt": "The Primal Return Retreat \u2013 Sierra Kliscz"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/food-5-300x300-342b7e50.jpg", "alt": "The Primal Return Retreat \u2013 Sierra Kliscz"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/35420810-b051-4517-8442-44d2b3d44068/gallery/sierra-kliscz-headshot-for-special-retreat-d914ab74.png", "alt": "The Primal Return Retreat \u2013 Sierra Kliscz"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
