insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('35420810-b051-4517-8442-44d2b3d44068', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Sierra Kliscz", "bio_html": "<p>Sierra Kliscz is a holistic healing facilitator, embodiment teacher, and founder of the Yog Collective, with over nine years of deep exploration in human wellness, ancestral movement, and transformational practice.</p> <p>Sierra has spent years studying the places where ancient wisdom meets the modern human experience, developing a teaching style that is equal parts raw, grounding, and expansive. She holds space with fierce compassion, creating environments where people feel safe enough to shed what no longer serves them and remember who they were before the world got loud.</p> <p>As the author of Sovereign Sexuality and founder of the School of Women&#8217;s Embodiment, Sierra brings a profound understanding of the body, the nervous system, and the power of ritual to everything she facilitates. Her work is not about performance or perfection. It is about return.</p> <p>The Primal Return is Sierra&#8217;s invitation to anyone who is ready to stop surviving and start living from a deeper, wilder, more connected place.</p>", "ao_person_id": "abb1c60b-396a-48a7-a230-f43f7b8e1557"}'::jsonb)
on conflict do nothing;
