values ('ee6afaac-3f31-42b9-a5d4-feea52aa96e4', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "b2976bf8-6196-42e9-8e3d-5669118e16ed", "heading": "Dates & Rates", "manual_dates_text": "Oct 24 - 31, 2026", "manual_tiers": [{"name": "Dorm", "price": "$895"}, {"name": "Triple", "price": "$1,095"}, {"name": "Double", "price": "$1,395"}, {"name": "Single", "price": "$1,995"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.secure.retreat.guru/program/radiant-heart-yoga-retreat-karen-mckinnon/?form=1&lang=en"}'::jsonb)
