insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('ee6afaac-3f31-42b9-a5d4-feea52aa96e4', 'c229572b-1c0d-446e-8c7c-f05b2852bb92', '{"html": "<p><strong>Rejuvenate your senses and replenish your soul.</strong></p>\n<p>Step away from the noise of your daily life and over-efforting, into a world of beauty, playfulness and deep nourishment.</p>\n<p>This retreat invites you to savor the pleasure of being fully alive in your body and heart. Surrounded by the jungle, you can indulge in daily yoga and transformational workshops\u2026 enjoy the spa and Costa Rican adventures\u2026 or simply slow down and be.</p>\n<p>Awaken your intuition, rejuvenate your senses, and replenish your body. There\u2019s something here for everyone.</p>\n<p><strong>If you\u2019re ready to come home to yourself \u2013 reserve your spot today.</strong></p>", "padding_y_px": 48}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('ee6afaac-3f31-42b9-a5d4-feea52aa96e4', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "Earth Radiance \u2013 The Power of Gentle", "price": "$50", "note": "90-minute workshop"}, {"name": "Sound Radiance \u2013 The Power of Your Voice", "price": "$50", "note": "90-minute workshop"}, {"name": "Dream Radiance \u2013 The Power of Inner Vision", "price": "$50", "note": "90-minute workshop"}], "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('ee6afaac-3f31-42b9-a5d4-feea52aa96e4', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>Earth Radiance \u2013 The Power of Gentle</h3><p><em>90-minute workshop &mdash; $50</em></p><p>A grounding somatic journey into your body\u2019s wisdom, releasing patterns of over-efforting and moving into deeper trust in your natural rhythm.Through powerful prompts and reflective exercises, connect with a more sustainable and satisfying way of creating; one that is gentle, alive and receptive.Radiate in your softness and blossom from the inside out.</p><h3>Sound Radiance \u2013 The Power of Your Voice</h3><p><em>90-minute workshop &mdash; $50</em></p><p>An embodied vocal experience of awakening your true expression. Through simple powerful mantras and movement, release layers of holding back. As you unclench and let your sound fly, your inner voice moves freely, expressing the truth of who you are with joy from the inside out.</p><h3>Dream Radiance \u2013 The Power of Inner Vision</h3><p><em>90-minute workshop &mdash; $50</em></p><p>A sensory journey into intuition, and dream-world awareness. Move out of linear thinking into the wisdom of your vision. Through guided reflection and intuitive exploration, awaken the power of symbolic language and how you and life speak with each other. Enter a deeper relationship with your creative soul guidance where vision becomes a living, felt experience that supports and inspires your waking life.</p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('ee6afaac-3f31-42b9-a5d4-feea52aa96e4', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/ee6afaac-3f31-42b9-a5d4-feea52aa96e4/gallery/hero-image-82-5d39039d.png", "alt": "Radiant Heart Retreat \u2013 Karen McKinnon"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/ee6afaac-3f31-42b9-a5d4-feea52aa96e4/gallery/lower-deck-yoga-class-cropped-300x300-51700eee.png", "alt": "Radiant Heart Retreat \u2013 Karen McKinnon"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/relax-on-the-pool-deck-at-anamaya-resort-300x300-87bae3ad.jpg", "alt": "Radiant Heart Retreat \u2013 Karen McKinnon"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/spa-1-300x300-c701562a.jpg", "alt": "Radiant Heart Retreat \u2013 Karen McKinnon"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/cristiane-link-300x300-c44147a2.jpg", "alt": "Radiant Heart Retreat \u2013 Karen McKinnon"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/food-5-300x300-342b7e50.jpg", "alt": "Radiant Heart Retreat \u2013 Karen McKinnon"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/ee6afaac-3f31-42b9-a5d4-feea52aa96e4/gallery/karen-mckinnon-headshot-ba0674de.png", "alt": "Radiant Heart Retreat \u2013 Karen McKinnon"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('ee6afaac-3f31-42b9-a5d4-feea52aa96e4', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Karen McKinnon", "bio_html": "<p>Karen brings with her over 23 years of experience as a certified Hatha Yoga Teacher, teaching classes, teacher trainings and retreats in Canada and abroad. With a diploma in Psychotherapy, she is also a Reiki master trained in Hospice Complimentary Reiki Care, and the Groove Dance Method.</p>\n<p>When Karen is not teaching, seeing clients 1:1 in Victoria BC for Intuitive Reiki and Soul Coaching, you can find her salsa dancing, singing, in the water, out for a walk in nature, knitting or weight lifting. Karen is passionate about celebrating your aliveness for a sacred and playful life, awakening your soul voice and heart that you can feel in your body. She believes there is nothing like feeling more at home your body, that soul communication is natural and feeling nourished is a way of living.</p>", "ao_person_id": "348c3c4a-c6af-467d-834d-df29755d73c7"}'::jsonb)
on conflict do nothing;
