values ('b5f1938d-692c-44ac-a1e0-4783741cb0e3', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "da13a811-ae40-4f0f-9966-60f2c3167b22", "heading": "Dates & Rates", "manual_dates_text": "March 6 - 13, 2027", "manual_tiers": [{"name": "Dorm", "price": "$1,095"}, {"name": "Triple", "price": "$1,295"}, {"name": "Double", "price": "$1,595"}, {"name": "Single", "price": "$2,195"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.secure.retreat.guru/program/survive-and-thrive-reset-retreat-terri-chloe-copy/?form=1&lang=en"}'::jsonb)
