insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('b5f1938d-692c-44ac-a1e0-4783741cb0e3', 'c229572b-1c0d-446e-8c7c-f05b2852bb92', '{"html": "<p><strong>You weren\u2019t meant to just survive\u2026 you were meant to thrive.</strong></p><p>If you\u2019ve been pouring from an empty cup, feeling drained by the world around you, and craving a deeper connection to yourself, this is your reset.</p><p>Join Terri and Chloe in the lush jungle of Costa Rica for a powerful week of healing, energy alignment, and transformation. Through guided workshops, nourishing practices, and elemental wisdom, you\u2019ll strengthen your boundaries, restore your vitality, and reconnect with the resilient, radiant you.</p><p><strong>This is more than a retreat \u2013 it\u2019s a return to your power.</strong></p><p>Survival of the fittest \u2013 is often understood as a physical concept, but true resilience comes from harmony within the body, mind, and spirit.</p><p>Join Terri & Chloe on a journey of self-discovery, where we cultivate inner strength, balance, and awareness. Through energy work, mindful boundaries, and deep stillness, we will guide you to not just survive, but thrive. Learn to honor your own space, protect your energy, and create boundaries that support your well-being \u2014all while aligning with the natural elements that shape us: <strong>Water, Earth, Ether, Air, and Fire.</strong></p>", "padding_y_px": 48}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('b5f1938d-692c-44ac-a1e0-4783741cb0e3', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "Tapping into your true nature through Pranayama & Meditation", "price": "$75\u2013$75", "note": "90-minute workshop"}, {"name": "Mindful Meditation and Mala Bracelet Workshop", "price": "$75\u2013$75", "note": "90-minute workshop"}, {"name": "Detoxing and Cleansing Workshop", "price": "$75\u2013$75", "note": "90-minute workshop"}, {"name": "All Workshops Package", "price": "$200", "note": "90-minute workshop"}, {"name": "Daily Meditations", "price": "$5\u2013$25", "note": "30-minute workshop"}], "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('b5f1938d-692c-44ac-a1e0-4783741cb0e3', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>Tapping into your true nature through Pranayama & Meditation</h3><p><em>90-minute workshop &mdash; $75\u2013$75</em></p><p>Tapping into your true nature through Pranayama &amp; Meditation, revealing who it is that is living this life! It is through the senses our spiritual nature lives and creates perceptions, blockages and openings. We will practice together these two limbs of Yoga to gain insight on who we are deep within and sometimes beyond our own comprehension. Discussion will ensue regarding the energy which we are made of, Prana, and how we can bring in healthier ways of living. You will learn ways to block negative energy through these practices, how to fuel and feed positive energy, block negative energy and detect when we are being pulled into a negative energy pattern creating Samskara\u2019s or habitual patterns we are ignoring.</p><h3>Mindful Meditation and Mala Bracelet Workshop</h3><p><em>90-minute workshop &mdash; $75\u2013$75</em></p><p>The mind is indeed a powerful tool capable of shaping our thoughts, beliefs, and actions, ultimately influencing our lives and well-being. Through the process of mindful meditation, mantra and creation of a beautiful Mala bracelet, you will learn ways to occupy the mind, and stop the negative patterns of self talk, healing and making our way back to our true nature. We will teach you, in this workshop, some beautifully powerful and peaceful mantras to promote peace, strength and spiritual growth. Each student will leave with a Mala bracelet of their own creation during this workshop.</p><h3>Detoxing and Cleansing Workshop</h3><p><em>90-minute workshop &mdash; $75\u2013$75</em></p><p>Detoxing, cleansing and eating your way back to a healthy physical body! We will share recipes, methods of preparation of foods, cleansing and detoxing the physical body to enhance our well being and thrive in this world we live in. The correlation of foods and the impact they have on our energetic and physical bodies will be taught.</p><h3>All Workshops Package</h3><p><em>90-minute workshop &mdash; $200</em></p><p>Pricing for all 3 workshops.</p><h3>Daily Meditations</h3><p><em>30-minute workshop &mdash; $5\u2013$25</em></p><p>Terri &amp; Chloe will be offering daily meditations.</p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('b5f1938d-692c-44ac-a1e0-4783741cb0e3', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/b5f1938d-692c-44ac-a1e0-4783741cb0e3/gallery/yoga_duarte12-e05cd41f.jpg", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/relax-on-the-pool-deck-at-anamaya-resort-300x300-87bae3ad.jpg", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/spa-1-300x300-c701562a.jpg", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/cristiane-link-300x300-c44147a2.jpg", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/f13a95ab-df1c-4198-9318-587528baa434/gallery/food_0016_layer-3-300x300-7e885354.jpg", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/f13a95ab-df1c-4198-9318-587528baa434/gallery/on-the-beach-with-tai-300x300-a38dc381.jpg", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/b5f1938d-692c-44ac-a1e0-4783741cb0e3/gallery/anamaya-headshot-13-504ab34b.png", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/b5f1938d-692c-44ac-a1e0-4783741cb0e3/gallery/terri-headshot-2023-799x800-f91690bf.png", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('b5f1938d-692c-44ac-a1e0-4783741cb0e3', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Chloe Haddad", "bio_html": "<p>Hi! I\u2019m Chlo\u00e9 from Rockford, Michigan. After many years in the fitness industry, I found my true passion in yoga and massage. I discovered that I love practicing and teaching yoga and helping people heal, relax, and release through massage. With countless hours of yoga studies and some amazing teachers guiding me, I focus on showing others that yoga is more than just about the poses; it\u2019s about calming the mind and connecting the mind, body, and spirit through breath. I\u2019m always learning, whether it\u2019s from my studies or the incredible clients I work with. I&#8217;m also fortunate to have some fantastic mentors who keep me inspired. When I&#8217;m not teaching or massaging, you might catch me on my paddle board practicing yoga on the lake, wandering the woods on long walks with my dogs, or exploring the underwater world\u2014I recently got scuba certified! I have a deep love for Anamaya and feel incredibly blessed to be returning to teach there again this year. I\u2019m excited to meet new people and make new friends along the way!</p>", "ao_person_id": "bf0ffc95-8d0b-49fa-b28f-63f6d5658d2c"}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('b5f1938d-692c-44ac-a1e0-4783741cb0e3', '4a08c4ca-1b80-4e05-871e-97f7dafe90f3', '{"responsive_mode": "fixed", "role": "Co-Teacher", "name": "Terri McDermott", "bio_html": "<p>Hello! I\u2019m Terri and I live the most amazing life split between being a part-time Michigan resident and part-time Florida resident, with additional travels and teaching experiences offered in beautiful places around the world. Spending much of my life in search of something more meaningful, deeper than what always has appeared just within reach and understanding, I found yoga or maybe I should say it found me. The years spent attempting to understand more about the human body, what drives us and how we function, the levels of consciousness and \u201cwho\u201d is the one behind thinking, acting, feeling and understanding have been my path. With over 20 years of combined studies in the medical, spiritual and yogic world I\u2019ve found the ways and means to assist you on your journey! The lineages and teachers I\u2019ve been blessed to have in my life have prepared me to share with you the skills, wisdom and practices of the past to unlock within you, your true connection to your healer, your \u201cBoddhisatva\u201d, YOU and your connection to the Divine! I am so excited to greet you with open arms to this path of self study, guidance, and your inner healer, no matter what path you are currently walking! Let\u2019s connect soon, here, at Anamaya Resort, to bring meaning to this life and connection to the energy of the surrounding tropical oasis and rainforest! I simply cannot wait to meet you!</p>", "ao_person_id": "6b2606df-bf00-49f4-a7f2-b447757b6080"}'::jsonb)
on conflict do nothing;
