insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('20a00dc7-0432-481d-ac22-4e9e892d9191', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "Tapping into your true nature through Pranayama & Meditation", "price": "$75\u2013$75", "note": "90-minute workshop"}, {"name": "Mindful Meditation and Mala Bracelet Workshop", "price": "$75\u2013$75", "note": "90-minute workshop"}, {"name": "Detoxing and Cleansing Workshop", "price": "$75\u2013$75", "note": "90-minute workshop"}, {"name": "All Workshops Package", "price": "$200", "note": "90-minute workshop"}, {"name": "Daily Meditations", "price": "$5\u2013$25", "note": "30-minute workshop"}], "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('20a00dc7-0432-481d-ac22-4e9e892d9191', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>Tapping into your true nature through Pranayama & Meditation</h3><p><em>90-minute workshop &mdash; $75\u2013$75</em></p><p>Tapping into your true nature through Pranayama &amp; Meditation, revealing who it is that is living this life! It is through the senses our spiritual nature lives and creates perceptions, blockages and openings. We will practice together these two limbs of Yoga to gain insight on who we are deep within and sometimes beyond our own comprehension. Discussion will ensue regarding the energy which we are made of, Prana, and how we can bring in healthier ways of living. You will learn ways to block negative energy through these practices, how to fuel and feed positive energy, block negative energy and detect when we are being pulled into a negative energy pattern creating Samskara\u2019s or habitual patterns we are ignoring.</p><h3>Mindful Meditation and Mala Bracelet Workshop</h3><p><em>90-minute workshop &mdash; $75\u2013$75</em></p><p>The mind is indeed a powerful tool capable of shaping our thoughts, beliefs, and actions, ultimately influencing our lives and well-being. Through the process of mindful meditation, mantra and creation of a beautiful Mala bracelet, you will learn ways to occupy the mind, and stop the negative patterns of self talk, healing and making our way back to our true nature. We will teach you, in this workshop, some beautifully powerful and peaceful mantras to promote peace, strength and spiritual growth. Each student will leave with a Mala bracelet of their own creation during this workshop.</p><h3>Detoxing and Cleansing Workshop</h3><p><em>90-minute workshop &mdash; $75\u2013$75</em></p><p>Detoxing, cleansing and eating your way back to a healthy physical body! We will share recipes, methods of preparation of foods, cleansing and detoxing the physical body to enhance our well being and thrive in this world we live in. The correlation of foods and the impact they have on our energetic and physical bodies will be taught.</p><h3>All Workshops Package</h3><p><em>90-minute workshop &mdash; $200</em></p><p>Pricing for all 3 workshops.</p><h3>Daily Meditations</h3><p><em>30-minute workshop &mdash; $5\u2013$25</em></p><p>Terri &amp; Chloe will be offering daily meditations.</p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
