values ('20a00dc7-0432-481d-ac22-4e9e892d9191', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/b5f1938d-692c-44ac-a1e0-4783741cb0e3/gallery/yoga_duarte12-e05cd41f.jpg", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/relax-on-the-pool-deck-at-anamaya-resort-300x300-87bae3ad.jpg", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/spa-1-300x300-c701562a.jpg", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/cristiane-link-300x300-c44147a2.jpg", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/f13a95ab-df1c-4198-9318-587528baa434/gallery/food_0016_layer-3-300x300-7e885354.jpg", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/f13a95ab-df1c-4198-9318-587528baa434/gallery/on-the-beach-with-tai-300x300-a38dc381.jpg", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/b5f1938d-692c-44ac-a1e0-4783741cb0e3/gallery/anamaya-headshot-13-504ab34b.png", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/b5f1938d-692c-44ac-a1e0-4783741cb0e3/gallery/terri-headshot-2023-799x800-f91690bf.png", "alt": "Survive and Thrive: A 21st Century Reset \u2013 Terri & Chloe"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
