insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('20a00dc7-0432-481d-ac22-4e9e892d9191', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Chloe Haddad", "bio_html": "<p>Hi! I\u2019m Chlo\u00e9 from Rockford, Michigan. After many years in the fitness industry, I found my true passion in yoga and massage. I discovered that I love practicing and teaching yoga and helping people heal, relax, and release through massage. With countless hours of yoga studies and some amazing teachers guiding me, I focus on showing others that yoga is more than just about the poses; it\u2019s about calming the mind and connecting the mind, body, and spirit through breath. I\u2019m always learning, whether it\u2019s from my studies or the incredible clients I work with. I&#8217;m also fortunate to have some fantastic mentors who keep me inspired. When I&#8217;m not teaching or massaging, you might catch me on my paddle board practicing yoga on the lake, wandering the woods on long walks with my dogs, or exploring the underwater world\u2014I recently got scuba certified! I have a deep love for Anamaya and feel incredibly blessed to be returning to teach there again this year. I\u2019m excited to meet new people and make new friends along the way!</p>", "ao_person_id": "bf0ffc95-8d0b-49fa-b28f-63f6d5658d2c"}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('20a00dc7-0432-481d-ac22-4e9e892d9191', '4a08c4ca-1b80-4e05-871e-97f7dafe90f3', '{"responsive_mode": "fixed", "role": "Co-Teacher", "name": "Terri McDermott", "bio_html": "<p>Hello! I\u2019m Terri and I live the most amazing life split between being a part-time Michigan resident and part-time Florida resident, with additional travels and teaching experiences offered in beautiful places around the world. Spending much of my life in search of something more meaningful, deeper than what always has appeared just within reach and understanding, I found yoga or maybe I should say it found me. The years spent attempting to understand more about the human body, what drives us and how we function, the levels of consciousness and \u201cwho\u201d is the one behind thinking, acting, feeling and understanding have been my path. With over 20 years of combined studies in the medical, spiritual and yogic world I\u2019ve found the ways and means to assist you on your journey! The lineages and teachers I\u2019ve been blessed to have in my life have prepared me to share with you the skills, wisdom and practices of the past to unlock within you, your true connection to your healer, your \u201cBoddhisatva\u201d, YOU and your connection to the Divine! I am so excited to greet you with open arms to this path of self study, guidance, and your inner healer, no matter what path you are currently walking! Let\u2019s connect soon, here, at Anamaya Resort, to bring meaning to this life and connection to the energy of the surrounding tropical oasis and rainforest! I simply cannot wait to meet you!</p>", "ao_person_id": "6b2606df-bf00-49f4-a7f2-b447757b6080"}'::jsonb)
on conflict do nothing;
