values ('b625eaa2-a2e9-456e-81dd-1a69d4c6a623', 'ca30fa78-411b-434c-acfa-0996a9a70fcf', '{"retreat_id": "8bab2715-d874-46dc-a367-449f1b3d6680", "heading": "Dates & Rates", "manual_dates_text": "Dec 19 \u2013 26, 2026", "manual_tiers": [{"name": "Dorm", "price": "$1,295"}, {"name": "Triple", "price": "$1,495"}, {"name": "Double", "price": "$1,795"}, {"name": "Single", "price": "$2,395"}], "manual_cta_label": "Book Now", "manual_cta_href": "https://anamaya.secure.retreat.guru/program/holiday-yoga-retreat-cristiane-machado/?form=1&lang=en"}'::jsonb)
