insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('b625eaa2-a2e9-456e-81dd-1a69d4c6a623', 'c229572b-1c0d-446e-8c7c-f05b2852bb92', '{"html": "<p>The holidays are supposed to feel magical. So why do most of us cross into January feeling worse than when we started?</p><p>The rushing. The overcommitting. The smile-through-it-all exhaustion. By the time December ends, you\u2019re not restored. You\u2019re depleted.</p><p>What if this year was different?</p><p>Join Cristiane at Anamaya Resort for a week designed to actually nourish you. Move through curated workshops, sacred cacao ceremony, and heart-opening yoga on an open-air deck above the Pacific. Or settle into a hammock with a good book and let the jungle do the work. There is no wrong way to be here.</p><p>You\u2019ll close out the year feeling clear, restored, and genuinely excited about what\u2019s next.</p><p><strong>This is the holiday you actually deserve. Book your spot today.</strong></p>", "padding_y_px": 48}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('b625eaa2-a2e9-456e-81dd-1a69d4c6a623', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "The Infinite Possibilities Workshop", "price": "$175", "note": "90-minute workshop"}, {"name": "Z-Fit Movement Workshop", "price": "$15", "note": "60-minute workshop"}, {"name": "The Alchemy of Breath: A 90-Minute Journey", "price": "$95", "note": "90-minute workshop"}, {"name": "Cacao Ceremony", "price": "$50", "note": "60-minute workshop"}], "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('b625eaa2-a2e9-456e-81dd-1a69d4c6a623', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>The Infinite Possibilities Workshop</h3><p><em>90-minute workshop &mdash; $175</em></p><p>Join Cristiane Machado, for the transformative &#8220;7 Principles of Infinite Possibilities Workshop.&#8221; This workshop combines the profound teachings of the Chakra system with the empowering principles of infinite possibilities.</p><p>During this workshop, you will dive deep into the seven chakras, understanding their significance and how they influence various aspects of your life. Together, we will explore practical exercises and engage in insightful discussions to help you tap into the limitless potential within you.</p><p>Through a combination of theory and experiential learning, you will discover how to align your chakras and harness their energy to manifest your desires and create a life of abundance and fulfillment. My passion for empowering individuals will guide you through this journey of self-discovery and transformation.</p><p>Don&#8217;t miss this opportunity to explore the depths of your being, unlock your true potential, and embrace the infinite possibilities that await you. Join me, Cristiane Machado, for the &#8220;7 Principles of Infinite Possibilities Workshop&#8221; and embark on a life-changing experience.</p><h3>Z-Fit Movement Workshop</h3><p><em>60-minute workshop &mdash; $15</em></p><p>This movement class based on self expression and the unlocking of our hips.</p><p>The music is international and the moves are simple and tantalizing. This is for everyone &#8211; even the non dancers &#8211; to get a fantastic workout that does not feel like a workout. It is a FUN, EASY and ENJOYABLE way to connect with our own bodies and one another with no attachment to performance. It is an invitation to LET IT GO and FEEL the sounds as we move! It is an opportunity to meet yourself exactly where you are and LOVE it!!!</p><h3>The Alchemy of Breath: A 90-Minute Journey</h3><p><em>90-minute workshop &mdash; $95</em></p><p>During this special workshop, discover the sacred power within you&#8230; your breath. This portal to presence guides you from reaction to creation, offering profound self-understanding and regulation. Walk away with practical techniques to weave magic into your daily life once you&#8217;re back at home.</p><h3>Cacao Ceremony</h3><p><em>60-minute workshop &mdash; $50</em></p><p><strong>Heart-opening ritual with sacred medicine</strong></p><p><em>\u201cChocolate is a divine, celestial drink, the sweat of the stars, the vital seed, divine nectar, the drink of the Gods.\u201d</em><br> \u2014 Antonio Laved\u00e1n, Spanish Army Surgeon, 1796</p><p>Cacao isn\u2019t just chocolate. It\u2019s medicine. Known as Theobroma cacao, \u201cFood of the Gods\u201d \u2013 this ceremonial-grade cacao is sourced from the BriBri Tribe of Costa Rica and prepared with intention, reverence, and ritual.</p><p>Rich in magnesium, antioxidants, and anandamide (the \u201cbliss molecule\u201d), cacao opens the heart, quiets the mind, and reconnects you to your truest self.</p><p><strong>What to expect:</strong><br> Cristiane will guide you through a traditional ceremony rooted in Mayan and Aztec wisdom. You\u2019ll sit in circle, sip blessed cacao, and be led through a meditative journey that clears the mind, opens the voice, and softens the heart.</p><p>Some people cry. Some laugh. Some feel tingling energy rise through their body. Many describe it as liberation.</p><p>There are no expectations here\u2026 only an invitation to feel what\u2019s been waiting beneath the surface.</p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('b625eaa2-a2e9-456e-81dd-1a69d4c6a623', 'd384555b-4b04-4acc-8826-de4825a1ec0e', '{"images": [{"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/b625eaa2-a2e9-456e-81dd-1a69d4c6a623/gallery/cristiane-link-d3300c0d.jpg", "alt": "Winter Escape Holiday Retreat \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/relax-on-the-pool-deck-at-anamaya-resort-300x300-87bae3ad.jpg", "alt": "Winter Escape Holiday Retreat \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/b625eaa2-a2e9-456e-81dd-1a69d4c6a623/gallery/img_5352-300x300-f024c432.jpg", "alt": "Winter Escape Holiday Retreat \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/yoga-bonus-300x300-e2ddbe11.jpg", "alt": "Winter Escape Holiday Retreat \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/spa-1-300x300-c701562a.jpg", "alt": "Winter Escape Holiday Retreat \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/027a4a94-a39f-4421-9338-878953d743db/gallery/food-5-300x300-342b7e50.jpg", "alt": "Winter Escape Holiday Retreat \u2013 Cristiane Machado"}, {"url": "https://azvdmibriuqrmexwtrja.supabase.co/storage/v1/object/public/retreat-media/staging/b625eaa2-a2e9-456e-81dd-1a69d4c6a623/gallery/cristiane-headshot-flower-093d79b2.png", "alt": "Winter Escape Holiday Retreat \u2013 Cristiane Machado"}], "layout": "grid", "columns": 3, "lightbox": true, "padding_y_px": 32}'::jsonb)
on conflict do nothing;
insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('b625eaa2-a2e9-456e-81dd-1a69d4c6a623', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Cristiane Machado", "bio_html": "<p>Cristiane Machado, a Brazilian-born citizen of the Universe, is a passionate advocate for reconnecting with our divine essence and collective consciousness through therapeutic tools. After moving to the USA in 1999 and attending the Florida School of Massage, Cristiane embarked on a transformative journey that deepened her connection to energy work, yoga, and meditation\u2014practices that reignited her spiritual awakening.</p><p>A dreamer at heart, Cristiane envisions a world of equality and community, where everyone is valued beyond societal labels. As a bodyworker, 200-hour yoga guide specializing in Hatha Yoga, and facilitator of well-being, she creates safe spaces for growth and transformation. Cristiane\u2019s journey led her to Montezuma, Costa Rica, where she continues to guide others in reawakening their divinity through yoga retreats, sacred cacao circles, and her YogaLoka Project.</p><p>Cristiane\u2019s teaching philosophy centers on Yoga as a lifelong practice, a path to self-knowledge, acceptance, and inner peace. She believes in the power of connecting breath, physical effort, and observation to achieve well-being and heal old patterns. Her inclusive teaching style blends Hatha, Yin, and laughing yoga, making the practice accessible to all. Cristiane\u2019s greatest joy is helping her students take their yoga practice off the mat and into the world, fostering kindness and connection.</p>", "ao_person_id": "ee6e48a8-2116-45ea-9b6c-a7f344e10bd7"}'::jsonb)
on conflict do nothing;
