values ('f91a7927-ee3f-4cfe-83b3-0b25422e334f', '403e929f-18cd-4fde-a6e1-685237575195', '{"heading": "Optional Workshops", "intro": "", "tiers": [{"name": "The Infinite Possibilities Workshop", "price": "$175", "note": "90-minute workshop"}, {"name": "Z-Fit Movement Workshop", "price": "$15", "note": "60-minute workshop"}, {"name": "The Alchemy of Breath: A 90-Minute Journey", "price": "$95", "note": "90-minute workshop"}, {"name": "Cacao Ceremony", "price": "$50", "note": "60-minute workshop"}], "padding_y_px": 32}'::jsonb)
