insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('f91a7927-ee3f-4cfe-83b3-0b25422e334f', 'aa9b32a9-9236-45b4-b6ea-4b386021a0d4', '{"html": "<h3>The Infinite Possibilities Workshop</h3><p><em>90-minute workshop &mdash; $175</em></p><p>Join Cristiane Machado, for the transformative &#8220;7 Principles of Infinite Possibilities Workshop.&#8221; This workshop combines the profound teachings of the Chakra system with the empowering principles of infinite possibilities.</p><p>During this workshop, you will dive deep into the seven chakras, understanding their significance and how they influence various aspects of your life. Together, we will explore practical exercises and engage in insightful discussions to help you tap into the limitless potential within you.</p><p>Through a combination of theory and experiential learning, you will discover how to align your chakras and harness their energy to manifest your desires and create a life of abundance and fulfillment. My passion for empowering individuals will guide you through this journey of self-discovery and transformation.</p><p>Don&#8217;t miss this opportunity to explore the depths of your being, unlock your true potential, and embrace the infinite possibilities that await you. Join me, Cristiane Machado, for the &#8220;7 Principles of Infinite Possibilities Workshop&#8221; and embark on a life-changing experience.</p><h3>Z-Fit Movement Workshop</h3><p><em>60-minute workshop &mdash; $15</em></p><p>This movement class based on self expression and the unlocking of our hips.</p><p>The music is international and the moves are simple and tantalizing. This is for everyone &#8211; even the non dancers &#8211; to get a fantastic workout that does not feel like a workout. It is a FUN, EASY and ENJOYABLE way to connect with our own bodies and one another with no attachment to performance. It is an invitation to LET IT GO and FEEL the sounds as we move! It is an opportunity to meet yourself exactly where you are and LOVE it!!!</p><h3>The Alchemy of Breath: A 90-Minute Journey</h3><p><em>90-minute workshop &mdash; $95</em></p><p>During this special workshop, discover the sacred power within you&#8230; your breath. This portal to presence guides you from reaction to creation, offering profound self-understanding and regulation. Walk away with practical techniques to weave magic into your daily life once you&#8217;re back at home.</p><h3>Cacao Ceremony</h3><p><em>60-minute workshop &mdash; $50</em></p><p><strong>Heart-opening ritual with sacred medicine</strong></p><p><em>\u201cChocolate is a divine, celestial drink, the sweat of the stars, the vital seed, divine nectar, the drink of the Gods.\u201d</em><br> \u2014 Antonio Laved\u00e1n, Spanish Army Surgeon, 1796</p><p>Cacao isn\u2019t just chocolate. It\u2019s medicine. Known as Theobroma cacao, \u201cFood of the Gods\u201d \u2013 this ceremonial-grade cacao is sourced from the BriBri Tribe of Costa Rica and prepared with intention, reverence, and ritual.</p><p>Rich in magnesium, antioxidants, and anandamide (the \u201cbliss molecule\u201d), cacao opens the heart, quiets the mind, and reconnects you to your truest self.</p><p><strong>What to expect:</strong><br> Cristiane will guide you through a traditional ceremony rooted in Mayan and Aztec wisdom. You\u2019ll sit in circle, sip blessed cacao, and be led through a meditative journey that clears the mind, opens the voice, and softens the heart.</p><p>Some people cry. Some laugh. Some feel tingling energy rise through their body. Many describe it as liberation.</p><p>There are no expectations here\u2026 only an invitation to feel what\u2019s been waiting beneath the surface.</p>", "padding_y_px": 24}'::jsonb)
on conflict do nothing;
