insert into public.page_block_overrides (url_inventory_id, variant_block_id, content)
values ('f91a7927-ee3f-4cfe-83b3-0b25422e334f', '45734b4c-b726-4800-ad19-2ea272bddb69', '{"responsive_mode": "fixed", "role": "Lead Teacher", "name": "Cristiane Machado", "bio_html": "<p>Cristiane Machado, a Brazilian-born citizen of the Universe, is a passionate advocate for reconnecting with our divine essence and collective consciousness through therapeutic tools. After moving to the USA in 1999 and attending the Florida School of Massage, Cristiane embarked on a transformative journey that deepened her connection to energy work, yoga, and meditation\u2014practices that reignited her spiritual awakening.</p><p>A dreamer at heart, Cristiane envisions a world of equality and community, where everyone is valued beyond societal labels. As a bodyworker, 200-hour yoga guide specializing in Hatha Yoga, and facilitator of well-being, she creates safe spaces for growth and transformation. Cristiane\u2019s journey led her to Montezuma, Costa Rica, where she continues to guide others in reawakening their divinity through yoga retreats, sacred cacao circles, and her YogaLoka Project.</p><p>Cristiane\u2019s teaching philosophy centers on Yoga as a lifelong practice, a path to self-knowledge, acceptance, and inner peace. She believes in the power of connecting breath, physical effort, and observation to achieve well-being and heal old patterns. Her inclusive teaching style blends Hatha, Yin, and laughing yoga, making the practice accessible to all. Cristiane\u2019s greatest joy is helping her students take their yoga practice off the mat and into the world, fostering kindness and connection.</p>", "ao_person_id": "ee6e48a8-2116-45ea-9b6c-a7f344e10bd7"}'::jsonb)
